<script setup lang="ts">
import { Head, Link, useForm, router } from '@inertiajs/vue3';
import { MountainSnow, Sun, ShieldCheck, Check, Eye, EyeOff } from 'lucide-vue-next';
import { ref } from 'vue';
import ThemeToggle from '../Components/ThemeToggle.vue';
import PwaControls from '../Components/PwaControls.vue';
const props=defineProps<{mode:'login'|'register';demoAvailable?:boolean}>();
const form=useForm({name:'',email:'',password:'',password_confirmation:'',remember:false});const visible=ref(false);const demoBusy=ref(false);
function submit(){form.post(props.mode==='register'?'/register':'/login',{onFinish:()=>form.reset('password','password_confirmation')});}
function demo(){demoBusy.value=true;router.post('/demo',{}, {onFinish:()=>demoBusy.value=false});}
</script>
<template><Head :title="mode==='register'?'Create your workspace':'Welcome back'"/><div class="auth-layout"><section class="auth-story"><img class="auth-landscape" src="/mountain-dawn.png" alt="Mountains at dawn"/><Link href="/" class="brand auth-brand"><MountainSnow :size="31"/>Personal OS<span class="brand-dot">.</span></Link><div class="auth-story-copy"><span class="eyebrow">YOUR LIFE. A LITTLE CLEARER.</span><h1>A place for your plans.<br/>Space for your life.</h1><p>Bring your days, ideas, and ambitions together.<br/>One meaningful step at a time.</p><div class="auth-feature"><span><Check :size="15"/> Know what matters today</span><span><Check :size="15"/> Connect small actions to big goals</span><span><Check :size="15"/> Build habits that stay with you</span></div></div><div class="auth-caption">Small progress today, a bigger future tomorrow.</div></section><main class="auth-form-side"><div class="auth-theme-toggle"><ThemeToggle/></div><div class="auth-form-wrap"><span class="auth-sun"><Sun :size="27" stroke-width="1.6"/></span><h2>{{mode==='register'?'Make yourself at home.':'Welcome back.'}}</h2><p class="auth-subtitle">{{mode==='register'?'Your personal workspace starts here.':'A fresh start, right where you left off.'}}</p><form @submit.prevent="submit"><label v-if="mode==='register'" class="form-field"><span>Your name</span><input v-model="form.name" required autocomplete="name" placeholder="Hery"/><small class="field-error" v-if="form.errors.name">{{form.errors.name}}</small></label><label class="form-field"><span>Email address</span><input v-model="form.email" type="email" autocomplete="email" placeholder="you@example.com" required/><small class="field-error" v-if="form.errors.email">{{form.errors.email}}</small></label><label class="form-field"><span>Password</span><div class="password-field"><input v-model="form.password" :type="visible?'text':'password'" :autocomplete="mode==='register'?'new-password':'current-password'" required :minlength="mode==='register'?10:undefined" :aria-describedby="mode==='register'?'password-help':undefined" placeholder="Enter your password"/><button type="button" class="btn-icon" :aria-label="visible?'Hide password':'Show password'" @click="visible=!visible"><EyeOff v-if="visible" :size="18"/><Eye v-else :size="18"/></button></div><small v-if="mode==='register'" id="password-help" class="muted">Use at least 10 characters, including a letter and a number.</small><small class="field-error" v-if="form.errors.password">{{form.errors.password}}</small></label><label v-if="mode==='register'" class="form-field"><span>Confirm password</span><input v-model="form.password_confirmation" :type="visible?'text':'password'" autocomplete="new-password" required placeholder="Enter password again"/></label><label v-else class="checkbox-label remember-label"><input type="checkbox" v-model="form.remember"/> Keep me signed in</label><button class="btn btn-primary auth-submit" :disabled="form.processing">{{form.processing?'Just a moment...':mode==='register'?'Create my workspace':'Open my workspace'}}</button></form><p class="auth-switch">{{mode==='register'?'Already have a workspace?':'New to Personal OS?'}} <Link :href="mode==='register'?'/login':'/register'">{{mode==='register'?'Sign in':'Create an account'}}</Link></p><template v-if="demoAvailable"><div class="auth-divider"><span>TAKE A LOOK AROUND</span></div><button class="btn btn-secondary demo-button" :disabled="demoBusy" @click="demo">{{demoBusy?'Opening workspace...':'Explore the demo workspace'}}</button><p class="demo-caption">Try the local demo with sample tasks, habits, and projects.</p></template><div class="auth-install"><PwaControls/></div><p class="auth-privacy"><ShieldCheck :size="15"/> A private space for your everyday life</p></div><span class="auth-footnote">PERSONAL OS · V1</span></main></div></template>
